// GENERATED by scripts/sync-shared.mjs from src/chess/notation.ts. Do not edit; run `npm run sync:shared`.
// Converts engine output (UCI, e.g. "g8f6") into the notation people read
// (SAN, e.g. "Nf6"), using chess.js for the rules. Pure, unit tested.
import { Chess } from "chess.js";
import type { Position } from "../engine/uci.js";

const PIECE_ORDER = "kqrbnp";

/** Builds the game for a position. Throws on an illegal move. */
export function gameAt({ fen, moves = [] }: Position): Chess {
  const game = new Chess(fen);
  for (const uci of moves) game.move(uciToMoveInput(uci));
  return game;
}

function uciToMoveInput(uci: string) {
  return { from: uci.slice(0, 2), to: uci.slice(2, 4), promotion: uci[4] };
}

/**
 * Plays a UCI line from `game` and returns it in SAN. Stops at the first move
 * that is not legal, so a bad engine line can never produce invented moves.
 */
export function uciLineToSan(game: Chess, line: string[]): string[] {
  const copy = new Chess(game.fen());
  const out: string[] = [];
  for (const uci of line) {
    try {
      out.push(copy.move(uciToMoveInput(uci)).san);
    } catch {
      break;
    }
  }
  return out;
}

/** "3... Nf6 4. d3 Bc5" — SAN with move numbers, starting from `game`. */
export function numberedLine(game: Chess, sans: string[]): string {
  const fenParts = game.fen().split(" ");
  let moveNo = Number(fenParts[5] ?? 1);
  let white = fenParts[1] === "w";
  const parts: string[] = [];
  sans.forEach((san, i) => {
    if (white) parts.push(`${moveNo}. ${san}`);
    else parts.push(i === 0 ? `${moveNo}... ${san}` : san);
    if (!white) moveNo++;
    white = !white;
  });
  return parts.join(" ");
}

/** The moves played so far, numbered: "1. e4 e5 2. Nf3 Nc6 3. Bc4". */
export function movesSoFar(game: Chess): string {
  const history = game.history({ verbose: true });
  const first = history[0];
  if (!first) return "(no moves yet)";
  return numberedLine(
    new Chess(first.before),
    history.map((m) => m.san),
  );
}

const PIECE_NAME = {
  k: ["king", "king"],
  q: ["queen", "queens"],
  r: ["rook", "rooks"],
  b: ["bishop", "bishops"],
  n: ["knight", "knights"],
  p: ["pawn", "pawns"],
} as const;

/**
 * Piece placement in words: "king e1; queen d1; rooks a1, h1; …". Words, not
 * "Qd1", so the coach doesn't echo piece squares that look like moves.
 */
export function pieceList(game: Chess, color: "w" | "b"): string {
  const byType = new Map<keyof typeof PIECE_NAME, string[]>();
  for (const row of game.board()) {
    for (const cell of row) {
      if (cell && cell.color === color)
        byType.set(cell.type, [...(byType.get(cell.type) ?? []), cell.square]);
    }
  }
  return [...PIECE_ORDER]
    .filter((t): t is keyof typeof PIECE_NAME => byType.has(t as keyof typeof PIECE_NAME))
    .map((t) => {
      const squares = byType.get(t)!.sort();
      const [one, many] = PIECE_NAME[t];
      return `${squares.length > 1 ? many : one} ${squares.join(", ")}`;
    })
    .join("; ");
}
